def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    color = next(v for v in set(v for row in grid for v in row) if v != bg)
    out=[row[:] for row in grid]
    # Resolve the endpoints of each segment by the endpoints of the contour
    # pattern: each consecutive matching-color pair makes a straight segment.
    for r in range(h):
        cs=[c for c in range(w) if grid[r][c]==color]
        for a,b in zip(cs,cs[1:]):
            for c in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    for c in range(w):
        rs=[r for r in range(h) if grid[r][c]==color]
        for a,b in zip(rs,rs[1:]):
            for r in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    return out

